def background_cutoff(seconds: int) -> str:
    return (datetime.now(timezone.utc) - timedelta(seconds=int(seconds))).isoformat(timespec="seconds")


def background_table_columns(conn: sqlite3.Connection, table_name: str) -> set:
    try:
        return {str(row["name"]) for row in conn.execute(f"PRAGMA table_info({table_name})").fetchall()}
    except Exception:
        return set()


def background_count_recent(
    conn: sqlite3.Connection,
    table_name: str,
    seconds: int,
    preferred_columns: Tuple[str, ...] = ("created_at", "updated_at", "started_at"),
) -> int:
    columns = background_table_columns(conn, table_name)
    time_column = next((column for column in preferred_columns if column in columns), "")
    if not time_column:
        return 0
    try:
        row = conn.execute(
            f"SELECT COUNT(*) AS c FROM {table_name} WHERE {time_column} >= ?",
            (background_cutoff(seconds),),
        ).fetchone()
        return int(row["c"] or 0)
    except Exception:
        return 0


