def background_table_size_bytes(conn: sqlite3.Connection) -> Dict[str, int]:
    try:
        rows = conn.execute(
            """
            SELECT name, SUM(pgsize) AS bytes
            FROM dbstat
            GROUP BY name
            """
        ).fetchall()
    except Exception:
        return {}
    table_names = set(BACKGROUND_TABLES)
    result: Dict[str, int] = {}
    for row in rows:
        name = str(row["name"] or "")
        if name in table_names:
            result[name] = int(row["bytes"] or 0)
    return result


def background_token_usage(payload: Dict[str, object]) -> Dict[str, int]:
    usage = payload.get("usage")
    if not isinstance(usage, dict):
        usage = payload

    def read_int(*keys: str) -> int:
        for key in keys:
            value = usage.get(key) if isinstance(usage, dict) else None
            try:
                if value is not None:
                    return int(value)
            except Exception:
                continue
        return 0

    prompt_tokens = read_int("prompt_tokens", "input_tokens")
    completion_tokens = read_int("completion_tokens", "output_tokens")
    total_tokens = read_int("total_tokens")
    if not (prompt_tokens or completion_tokens or total_tokens):
        estimated = background_estimate_token_usage(payload)
        prompt_tokens = estimated["input_tokens"]
        completion_tokens = estimated["output_tokens"]
        total_tokens = estimated["total_tokens"]
    if not total_tokens:
        total_tokens = prompt_tokens + completion_tokens
    return {
        "input_tokens": prompt_tokens,
        "output_tokens": completion_tokens,
        "total_tokens": total_tokens,
    }


def background_estimate_text_tokens(value: object) -> int:
    text = str(value or "")
    if not text:
        return 0
    return max(1, int((len(text) + 1) / 2))


def background_estimate_token_usage(payload: Dict[str, object]) -> Dict[str, int]:
    input_tokens = 0
    output_tokens = 0
    input_keys = {
        "message",
        "messages",
        "prompt",
        "input",
        "input_preview",
        "query",
        "request",
        "source",
        "user_message",
        "content",
    }
    output_keys = {
        "answer",
        "response",
        "result",
        "decision",
        "summary",
        "output",
        "optimized_prompt",
        "translation",
        "memory",
    }

    def walk(value: object, hint: str = "") -> None:
        nonlocal input_tokens, output_tokens
        if isinstance(value, dict):
            for key, child in value.items():
                lower_key = str(key).lower()
                if lower_key == "answer_chars":
                    try:
                        output_tokens += background_estimate_text_tokens("x" * int(child or 0))
                    except Exception:
                        pass
                    continue
                if lower_key in {"prompt_chars", "input_chars"}:
                    try:
                        input_tokens += background_estimate_text_tokens("x" * int(child or 0))
                    except Exception:
                        pass
                    continue
                next_hint = hint
                if lower_key in output_keys:
                    next_hint = "output"
                elif lower_key in input_keys:
                    next_hint = "input"
                walk(child, next_hint)
            return
        if isinstance(value, list):
            for child in value:
                walk(child, hint)
            return
        if not isinstance(value, str) or not value:
            return
        tokens = background_estimate_text_tokens(value)
        if hint == "output":
            output_tokens += tokens
        else:
            input_tokens += tokens

    walk(payload)
    total_tokens = input_tokens + output_tokens
    return {
        "input_tokens": input_tokens,
        "output_tokens": output_tokens,
        "total_tokens": total_tokens,
    }


